import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { spawnSync } from 'node:child_process';
const dir = mkdtempSync(join(tmpdir(), 'viewstem-review-reporter-'));
const fixturePaths = ['controls', 'overlays', 'display'].map(group => resolve(`packages/svelte-ui/test/fixtures/audit-${group}.json`));
const reporter = resolve('packages/svelte-ui/scripts/audit-reporter.mjs');
try {
  const fixture = join(dir, 'cases.test.mjs');
  writeFileSync(fixture, `import test from 'node:test';
import {readFileSync} from 'node:fs';
const names=${JSON.stringify(fixturePaths)}.flatMap(path=>JSON.parse(readFileSync(path))).flatMap(row=>row.testNames);
for (const [i,name] of names.entries()) {
  if(i===0 && process.env.REVIEW_AUDIT_SCENARIO==='missing') continue;
  test(name,{skip:i===0&&process.env.REVIEW_AUDIT_SCENARIO==='skip'},()=>{
    if(i===0&&process.env.REVIEW_AUDIT_SCENARIO==='fail') throw new Error('intentional review failure');
  });
}
if(process.env.REVIEW_AUDIT_SCENARIO==='extra-fail') test('review/non-required failure',()=>{throw new Error('intentional extra failure');});
`);
  const results = [];
  for (const scenario of ['pass', 'missing', 'skip', 'fail', 'extra-fail']) {
    const r = spawnSync(process.execPath, ['--test', `--test-reporter=${reporter}`, fixture], {encoding:'utf8', env:{...process.env, REVIEW_AUDIT_SCENARIO:scenario}});
    if (r.error) throw r.error;
    assert.equal(r.status, scenario === 'pass' ? 0 : 1, `${scenario}: ${r.stderr}`);
    let report; try {report=JSON.parse(r.stdout);} catch {}
    if(scenario==='pass'||scenario==='extra-fail') assert.equal(report.audit.missing.length,0);
    results.push({scenario,exitStatus:r.status,reportFamilies:report?.audit.passedFamilies,reportMissing:report?.audit.missing.length,failedOutcomes:report?.outcomes.filter(t=>t.status==='failed').length,missingRejected:r.stderr.includes('Unverified shadcn family behavior cases')});
  }
  console.log(JSON.stringify({node:process.version,results},null,2));
} finally {rmSync(dir,{recursive:true,force:true});}
